import {makeSong} from './synthetic';
import type {LibrarySnapshot, ReadPath} from '../../panel/core/model';
export const paths = {account:'/api/w/nuser/account/get',list:'/api/user/playlist',playlist:'/api/v6/playlist/detail',song:'/api/v3/song/detail',ugc:'/api/rep/ugc/song/get'} as const;
export const detail = (id:number) => ({id,name:`合成歌曲 ${id}`,ar:[{id:11,name:'合成甲'},{id:12,name:'合成乙'}]});
export function snapshot(count=4,uid='7'):LibrarySnapshot {const ids=Array.from({length:count},(_,i)=>String(i+1));return {uid,sourcePlaylistId:'8',declaredCount:count,ids,songs:ids.map((id,position)=>({...makeSong(id,{genres:null,bpm:null,language:null}),position})),revision:JSON.stringify(ids)};}
export function libraryProvider(count=1419) { const ids=Array.from({length:count},(_,i)=>i+1);const detailBatchSizes:number[]=[];const called:string[]=[];return {detailBatchSizes,called,read:async (path:ReadPath,data:Record<string,unknown>):Promise<unknown>=>{called.push(path);switch(path){case paths.account:return {code:200,profile:{userId:7}};case paths.list:return {code:200,more:false,playlist:[{id:8,specialType:5,creator:{userId:7}}]};case paths.playlist:return {code:200,playlist:{id:8,trackCount:count,trackIds:ids.map(id=>({id})),tracks:ids.slice(0,1000).map(detail)}};case paths.song:{const batch=JSON.parse(String(data.c)) as {id:number}[];detailBatchSizes.push(batch.length);return {code:200,songs:batch.map(x=>detail(x.id))};}default:throw Error('unexpected path');}}};}
export function memoryStorage(){const data=new Map<string,string>();return {data,get length(){return data.size},key(i:number){return [...data.keys()][i]??null},getItem(k:string){return data.get(k)??null},setItem(k:string,v:string){data.set(k,v)},removeItem(k:string){data.delete(k)}};}
